function mailToLink(subject, body) {
  let url = "mailto:" + MAIL + "?subject=" + encodeURIComponent(subject);
  if (body) {
    url += "&body=" + encodeURIComponent(body);
  }
  return url;
}

function renderList(array) {
  return "<ul>" + array.map(item => "<li>" + item + "</li>").join("") + "</ul>";
}

function createDiagramNode(x, y, key, iconSvg) {
  return `
    <a href="#/d/${key}" aria-label="${D[key].t}">
      <circle cx="${x}" cy="${y}" r="40" fill="#fff" stroke="#c3cfe0" stroke-width="3"/>
      <g transform="translate(${x} ${y})" fill="none" stroke="#031f3d" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        ${iconSvg}
      </g>
      <text x="${x}" y="${y + 60}" text-anchor="middle" fill="#fff" font-size="15">
        ${D[key].t.split(" ")[0]}
      </text>
    </a>
  `;
}

