function renderDirectionCards() {
  return "<div class='grid'>" + Object.keys(D).map(key => `
    <a class="card" href="#/d/${key}">
      <span class="ic" aria-hidden="true">${D[key].i}</span>
      <h3>${D[key].t}</h3>
      <p>${D[key].d}</p>
    </a>
  `).join("") + "</div>";
}

function renderCallToActions(subject) {
  return `
    <a class="btn" href="#/book">დაჯავშნეთ კონსულტაცია</a>
    <a class="btn o" href="tel:${TEL}">დაგვირეკეთ</a>
  `;
}


function getPageContent(route) {
  const params = route.split("/").filter(Boolean);

  if (!params.length) {
    return `
      <section class="hero">
        <div>
          <h1>ბიზნესის სამართლებრივი, ფინანსური და უსაფრთხო გარემო – ერთ სივრცეში</h1>
          <p>TKD გთავაზობთ იურიდიულ, საბუღალტრო, საგადასახადო და შრომის უსაფრთხოების მომსახურებას.</p>
          <p>საიტზე შეგიძლიათ გაეცნოთ სერვისებს, ჩვენს გუნდს, ჩაეწეროთ ონლაინ ან ოფლაინ კონსულტაციაზე და წაიკითხოთ საჭირო სტატიები.</p>
          <a class="btn" href="#/book">ჩაეწერეთ კონსულტაციაზე</a>
          <a class="btn o" href="#/about">ჩვენ შესახებ</a>
        </div>
        ${mainDiagramSvg}
      </section>
      <section>
        <h2>ძირითადი მიმართულებები</h2>
        ${renderDirectionCards()}
      </section>
    `;
  }

  if (params[0] === "about") {
    return `
      <section>
        <h2>ჩვენ შესახებ</h2>
        <p>TKD მრავალპროფილური საკონსულტაციო კომპანიაა, რომელიც იურიდიულ და ფიზიკურ პირებს აკავშირებს ადვოკატებთან, შრომის უსაფრთხოების სპეციალისტებთან, ბუღალტრებთან და აუდიტორებთან. ერთი პარტნიორი ოთხი მიმართულებით — მარტივად, გამჭვირვალედ და სანდოდ.</p>
      </section>
      <section class="d">
        <div>
          <h2>ჩვენი მისია და ღირებულებები</h2>
          <p style="margin-bottom:20px">ჩვენი მთავარი მიზანია შევქმნათ მყარი, სანდო და უსაფრთხო გარემო თითოეული კლიენტისთვის. გვჯერა, რომ სასურველ შედეგს მხოლოდ პასუხისმგებლიანი, გულმოდგინე და კეთილსინდისიერი დამოკიდებულება იძლევა.</p>
          <div class="grid">
            ${VAL.map((v, i) => `
              <div class="card">
                <span class="num">0${i + 1}</span>
                <h3>${v[0]}</h3>
                <p>${v[1]}</p>
              </div>
            `).join("")}
          </div>
        </div>
      </section>
      <section>
        <h2>ჩვენი გუნდი</h2>
        <p>დამფუძნებელი პარტნიორები</p>
        ${TEAM.map(member => `
          <details>
            <summary>${member[0]}</summary>
            <div>
              <p>${member[1]}</p>
              <h4>განათლება</h4>
              ${renderList(member[2])}
              <h4>სამუშაო გამოცდილება</h4>
              ${renderList(member[3])}
            </div>
          </details>
        `).join("")}
      </section>
    `;
  }

  if (params[0] === "d" && D[params[1]]) {
    const dir = D[params[1]];
    return `
      <section>
        <div class="bc"><a href="#/">მთავარი</a> › ${dir.t}</div>
        <h1><span class="ic" aria-hidden="true">${dir.i}</span>${dir.t}</h1>
        <p>${dir.d}</p>
        <h2 style="margin-top:30px">სერვისები</h2>
        <div class="grid">
          ${S.filter(s => s[0] === params[1]).map(s => `
            <a class="card" href="#/s/${s[1]}">
              <h3>${s[2]}</h3>
              <p>${s[3].length > 120 ? s[3].slice(0, 110) + "…" : s[3]}</p>
            </a>
          `).join("")}
        </div>
        ${renderCallToActions(dir.t)}
      </section>
    `;
  }

  if (params[0] === "s") {
    const service = S.find(x => x[1] === params[1]);
    if (service) {
      const dir = D[service[0]];
      return `
        <section>
          <div class="bc"><a href="#/">მთავარი</a> › <a href="#/d/${service[0]}">${dir.t}</a> › ${service[2]}</div>
          <h1>${service[2]}</h1>
          <p>${service[3]}</p>
          <div class="box">
            <h3>ფასი</h3>
            <p>${dir.p}</p>
          </div>
          <div class="box">
            <h3>პირობები</h3>
            <p>${dir.c}</p>
          </div>
          ${service[1] === "criminal" ? `<p><b>24/7:</b> <a href="tel:${TEL}">+995 558 00 24 22</a></p>` : ""}
          <a class="btn" href="#/book/${service[1]}">ჯავშნა</a>
          <a class="btn o" href="${mailToLink("შეკითხვა: " + service[2])}">დაგვიკავშირდით</a>
        </section>
      `;
    }
  }

  if (params[0] === "law") {
    return `
      <section class="d" style="min-height:70vh">
        <div>
          <h2>კანონმდებლობა</h2>
          <p>ძირითადი აქტები საქართველოს საკანონმდებლო მაცნეზე:</p>
          <ul class="l">
            ${LAW.map(item => `
              <li>
                <a href="https://matsne.gov.ge/ka/document/view/${item[1]}" target="_blank" rel="noopener">${item[0]}</a>
              </li>
            `).join("")}
          </ul>
        </div>
      </section>
    `;
  }

  if (params[0] === "tpl") {
    return `
      <section>
        <h2>შაბლონები</h2>
        <div class="grid">
          ${TPL.map(tpl => `
            <div class="card">
              <h3>${tpl}</h3>
              <a class="btn" href="${mailToLink("შაბლონი: " + tpl)}" aria-label="მოითხოვე: ${tpl}">მოითხოვე</a>
            </div>
          `).join("")}
        </div>
      </section>
    `;
  }

  if (params[0] === "faq") {
    return `
      <section>
        <h2>ხშირად დასმული კითხვები</h2>
        ${FAQ.map((group, idx) => `
          <h3 style="margin-top:24px">${idx + 1}. ${group[0]}</h3>${group[1].map(q => `
            <details>
              <summary>${q[0]}</summary>
              <div><p>${q[1]}</p></div>
            </details>
          `).join("")}
        `).join("")}
      </section>
    `;
  }

  if (params[0] === "blog") {
    return `
      <section>
        <h2>ბლოგი</h2>
        <div class="grid">
          ${["პირველი საათები დაკავებისას", "შრომის უსაფრთხოება ბიზნესისთვის", "საგადასახადო დაგეგმვა"].map(title => `
            <div class="card">
              <h3>${title}</h3>
              <p>მალე გამოქვეყნდება.</p>
            </div>
          `).join("")}
        </div>
      </section>
    `;
  }

  if (params[0] === "contact") {
    return `
      <section>
        <h2>კონტაქტი</h2>
        <p>მისამართი: ქ. ბათუმი, ზურაბ გორგილაძის №69</p>
        <p>ტელეფონი: <a href="tel:+995558002422">+995 558 00 24 22</a></p>
        <p>E-mail: <a href="mailto:${MAIL}">${MAIL}</a></p>
        <p>Facebook: <a href="https://www.facebook.com/share/1MeXf5sW9k/" target="_blank" rel="noopener">tkdllc</a></p>
        <p>Instagram: <a href="https://www.instagram.com/tkd_llc" target="_blank" rel="noopener">@tkd_llc</a></p>
        ${renderCallToActions("კონსულტაციაზე ჩაწერა")}
      </section>
    `;
  }

  return `
    <section>
      <h2>გვერდი ვერ მოიძებნა</h2>
      <a class="btn" href="#/">მთავარი</a>
    </section>
  `;
}


