const repFields = (k, role) => [
  [k + "r", role + "ს წარმომადგენელი (თუ არსებობს)"],
  [k + "rp", "წარმომადგენლის პირადი №"],
  [k + "rx", "მინდობილობა: თარიღი, ნოტარიუსი, სანოტარო რეესტრის №"]
];
const objFields = (p, label) => [
  [p + "addr", label + " – მისამართი"],
  [p + "cad", label + " – საკადასტრო კოდი"],
  [p + "full", label + " – ფართობი (სრულად)"],
  [p + "part", label + " – ფართობი (ნაწილი)"]
];
const regFields = [["reg", "რეესტრის ამონაწერის №"], ["regd", "ამონაწერის მომზადების თარიღი", "date"]];

const mkTools = (getVal, getDateVal, val) => ({
  who: (k, p) => `${getVal(k)} (პირადი № ${getVal(p)})`,
  rep: (k) => val[k + "r"] ? ` წარმომადგენლის ${getVal(k + "r")} (პირადი № ${getVal(k + "rp")}) მეშვეობით, მოქმედი ${getVal(k + "rx")}` : "",
  obj: (p) => `მისამართი: ${getVal(p + "addr")}<br>საკადასტრო კოდი: ${getVal(p + "cad")}` +
    ((val[p + "full"] || !val[p + "part"]) ? `<br>ფართობი (სრულად): ${getVal(p + "full")}` : "") +
    (val[p + "part"] ? `<br>ფართობი (ნაწილი): ${getVal(p + "part")}` : ""),
  sig: (k, label) => `<div>${label}<br>${val[k] ? escapeHtml(val[k]) : '<span class="bl">........................</span>'}<br>/ხელმოწერა: ____________/</div>`,
  sigRep: (k, label) => val[k + "r"] ? `<div>${label}<br>${escapeHtml(val[k + "r"])}<br>/ხელმოწერა: ____________/</div>` : "",
  head: (title, ) => `<h3>${title}</h3>`
});

const courtTail = "ხელშეკრულებით გაუთვალისწინებელი სხვა პირობების მიმართ მოქმედებს საქართველოს სამოქალაქო კოდექსის ნორმები, ხოლო მხარეთა შორის დავის წარმოშობის შემთხვევაში დავას განიხილავს სასამართლო.";
