const templateIds = ["sale", "gift", "lease", "rent"];

function generateDocumentHtml(id) {
  const tpl = contractTemplates[id];
  const val = templateValues[id] || {};

  const getVal = key => val[key] ? escapeHtml(val[key]) : '<span class="bl">..................</span>';
  const getDateVal = key => val[key] ? escapeHtml(formatDate(val[key])) : '<span class="bl">....../....../........</span>';
  if (tpl.doc) return tpl.doc(getVal, getDateVal, val);
  
  const getRepresentative = (r, p, m) => val[r] ? ` წარმომადგენლის ${getVal(r)} (პირადი № ${getVal(p)}) მეშვეობით, მოქმედი ${getVal(m)}` : "";
  const getPartyInfo = (k, p, r, rp, rx) => `${getVal(k)} (პირადი № ${getVal(p)})` + (id === "gift" ? getRepresentative(r, rp, rx) : "");

  let headerHtml = id === "gift"
    ? `წინამდებარე ხელშეკრულების მხარეები შევთანხმდით შემდეგზე: ${getPartyInfo("A", "Ap", "Ar", "Arp", "Arx")}, რომელიც ამ ხელშეკრულებაში შემდგომში მოხსენიებულია როგორც „მჩუქებელი“, აჩუქა და ${getPartyInfo("B", "Bp", "Br", "Brp", "Brx")}, რომელიც ამ ხელშეკრულებაში შემდგომში მოხსენიებულია როგორც „დასაჩუქრებული“, მიიღო მჩუქებლის საკუთრებაში არსებული უძრავი ნივთი.`
    : `წინამდებარე ხელშეკრულების მხარეებმა: ${tpl.head(`${getVal("A")} (პირადი № ${getVal("Ap")})`, `${getVal("B")} (პირადი № ${getVal("Bp")})`)}`;

  const areaHtml = (val.full || !val.part ? `<br>ფართობი (სრულად): ${getVal("full")}` : "") + (val.part ? `<br>ფართობი (ნაწილი): ${getVal("part")}` : "");
  const signatureBlock = (key, label) => `<div>${label}<br>${val[key] ? escapeHtml(val[key]) : '<span class="bl">........................</span>'}<br>/ხელმოწერა: ____________/</div>`;

  return `
    <h3>${tpl.full}</h3>
    <p>ქ. ${getVal("city")} <span style="float:right">${getDateVal("date")}</span></p>
    <p>${headerHtml}</p>
    <p><b>ხელშეკრულების საგნის აღწერა:</b><br>მისამართი: ${getVal("addr")}<br>საკადასტრო კოდი: ${getVal("cad")}${areaHtml}</p>
    <p>აღნიშნულ უძრავ ნივთზე ${tpl.ow} საკუთრების უფლება დასტურდება ამონაწერით საჯარო რეესტრიდან № ${getVal("reg")}, მომზადების თარიღი ${getDateVal("regd")}.</p>
    ${tpl.mid(getVal)}
    <p>${tpl.tail}</p>
    <p>წინამდებარე ხელშეკრულების ტექსტი სრულიად შეესაბამება და გამოხატავს მხარეთა ნებას, რასაც ვადასტურებთ მხარეთა ხელმოწერით:</p>
    <div class="sg">
      ${signatureBlock("A", tpl.a)}
      ${signatureBlock("B", tpl.b)}
    </div>
  `;
}

function renderTemplatePage(id) {
  const tpl = contractTemplates[id];
  templateValues[id] = templateValues[id] || {};

  const fields = tpl.fields || [...getActorFields(tpl.a, tpl.b), ...propertyFields, ...tpl.more];
  const inputHtml = f => `
    <label>
      ${f[1]}
      <input data-t="${id}" data-k="${f[0]}" type="${f[2] || "text"}" value="${escapeHtml(templateValues[id][f[0]] || "")}">
    </label>
  `;

  return `
    <section lang="ka">
      <p class="en-only a-note" lang="en">This online form and contract text are in Georgian, as the document is governed by Georgian law.</p>
      <div class="bc nop"><a href="#/">მთავარი</a> › <a href="#/tpl">შაბლონები</a> › ${tpl.t}</div>
      <h1>${tpl.t}</h1>
      <p class="nop" style="margin-bottom:18px">შეავსეთ ველები — ხელშეკრულების ტექსტი მარჯვნივ ავტომატურად განახლდება. დაუსრულებელი ველები დარჩება წერტილებით, ხელით შესავსებად.</p>
      <div class="tw">
        <div class="fm nop">
          ${fields.map(inputHtml).join("")}
          <button class="btn" type="button" onclick="window.print()">ბეჭდვა / PDF-ად შენახვა</button>
          <a class="btn o" href="templates/${id}.docx" download="${tpl.t}.docx">ჩამოტვირთვა (.docx)</a>
          <a class="btn o" href="#" onclick="return sendTemplateViaMail('${id}')">გამოგვიგზავნეთ გადასამოწმებლად</a>
          <p style="font-size:13px;opacity:.8">შაბლონი საინფორმაციო ხასიათისაა; გადასამოწმებლად ან ინდივიდუალური პირობებისთვის <a href="#/book">დაჯავშნეთ კონსულტაცია</a>.</p>
        </div>
        <div class="doc" id="doc">${generateDocumentHtml(id)}</div>
      </div>
    </section>
  `;
}

document.addEventListener("input", function (e) {
  const target = e.target;
  if (target.dataset && target.dataset.t) {
    templateValues[target.dataset.t][target.dataset.k] = target.value;
    const docContainer = document.getElementById("doc");
    if (docContainer) {
      docContainer.innerHTML = generateDocumentHtml(target.dataset.t);
    }
  }
});

function sendTemplateViaMail(id) {
  const values = templateValues[id] || {};
  const bodyText = Object.keys(values)
    .filter(k => values[k])
    .map(k => k + ": " + values[k])
    .join("\n");

  window.location.href = "mailto:" + MAIL + 
    "?subject=" + encodeURIComponent("შაბლონის გადამოწმება: " + contractTemplates[id].t) + 
    "&body=" + encodeURIComponent("გამარჯობა, გთხოვთ გადაამოწმოთ ჩემი შევსებული შაბლონი.\n\n" + bodyText);
  
  return false;
}

