(function () {
  const norm = s => s.replace(/\s+/g, " ").trim();
  let lang = "ka";
  try { if (localStorage.getItem("tkd_lang") === "en") lang = "en"; } catch (e) {}
  const KA = new WeakMap(), AK = new WeakMap();
  const ATTRS = ["aria-label", "placeholder", "title", "alt"];
  const SKIP = '[lang="ka"]:not(html),[data-notr],script,style,noscript';

  function T(s) {
    if (lang !== "en") return s;
    const k = norm(s);
    if (EN[k]) return EN[k];
    const m = k.match(/^(› )(.+)$/);
    if (m) return m[1] + T(m[2]);
    const i = k.indexOf(": ");
    if (i > 0 && EN[k.slice(0, i)]) return EN[k.slice(0, i)] + ": " + T(k.slice(i + 2));
    return s;
  }
  window.T = T;

  function doText(n) {
    const p = n.parentElement;
    if (!p || p.closest(SKIP)) return;
    if (!KA.has(n)) KA.set(n, n.nodeValue);
    const o = KA.get(n);
    if (lang === "en" && norm(o)) {
      const t = T(o);
      if (t !== o) { n.nodeValue = o.match(/^\s*/)[0] + t + o.match(/\s*$/)[0]; return; }
    }
    if (n.nodeValue !== o) n.nodeValue = o;
  }

  function doAttrs(el) {
    if (el.closest(SKIP)) return;
    const m = AK.get(el) || {};
    ATTRS.forEach(a => {
      if (!el.hasAttribute(a)) return;
      if (!(a in m)) m[a] = el.getAttribute(a);
      const v = lang === "en" ? T(m[a]) : m[a];
      if (el.getAttribute(a) !== v) el.setAttribute(a, v);
    });
    AK.set(el, m);
  }

  function walk(root) {
    if (root.nodeType === 3) return doText(root);
    if (root.nodeType !== 1 || root.closest(SKIP)) return;
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let n; while ((n = w.nextNode())) doText(n);
    const sel = "[aria-label],[placeholder],[title],[alt]";
    if (root.matches(sel)) doAttrs(root);
    root.querySelectorAll(sel).forEach(doAttrs);
  }

  function updateTitle() {
    const h = document.querySelector("#app h1") || document.querySelector("#app h2");
    let t = "";
    if (h) { const c = h.cloneNode(true); c.querySelectorAll("[aria-hidden]").forEach(x => x.remove()); t = norm(c.textContent) + " | "; }
    document.title = t + (lang === "en" ? "TKD LLC | TKD" : "შპს თი ქეი დი | TKD");
  }

  const btn = document.getElementById("lg");
  function setLang(l) {
    lang = l;
    try { localStorage.setItem("tkd_lang", l); } catch (e) {}
    document.documentElement.lang = l;
    walk(document.body);
    btn.textContent = l === "en" ? "ქართული" : "English";
    btn.lang = l === "en" ? "ka" : "en";
    updateTitle();
  }
  btn.onclick = () => setLang(lang === "en" ? "ka" : "en");

  new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(walk))).observe(document.body, { childList: true, subtree: true });
  setLang(lang);
})();
